49 method isSubstring(sub: string, str: string) returns (res:bool)
50 	ensures  res <==> isSubstringPred(sub, str)
51 	//ensures !res <==> isNotSubstringPred(sub, str) // This postcondition follows from the above lemma.
52 {
53     // Initializing variables
54 	var i := 0;
55     res := false;
56     // Check if sub is a prefix of str[i..] and if not, keep incrementing until i = |str| 
57     while i <= |str|
58     // Invariant to stay within bounds
59     // Invariant to show that for all j that came before i, no prefix has been found
60     invariant forall j :: (0 <= j < i ==> isNotPrefixPred(sub, str[j..]))
61     // Telling dafny that i is that value that is increasing
62     decreases |str| - i
63     //invariant res <==> isSubstringPred(sub, str)
64     {
65         // Check if the substring is a prefix
66         var temp := isPrefix(sub, str[i..]);
67         // If so, return true as the prefix is a substring of the string
68         if  temp == true 
69         {
70             return true;
71         }
72         // Otherwise, increment i and try again
73         i := i + 1;
74     } 
75     // If we have reached this point, it means that no substring has been found, hence return false
76     return false;
77 }
