80 predicate haveCommonKSubstringPred(k:nat, str1:string, str2:string)
81 {
82 	exists i1, j1 :: 0 <= i1 <= |str1|- k && j1 == i1 + k && isSubstringPred(str1[i1..j1],str2)
83 }
84 
85 predicate haveNotCommonKSubstringPred(k:nat, str1:string, str2:string)
86 {
87 	forall i1, j1 :: 0 <= i1 <= |str1|- k && j1 == i1 + k ==>  isNotSubstringPred(str1[i1..j1],str2)
88 }
