99     // Check that both strings are larger than k 
100     if (k > |str1| || k > |str2| ){
101         return false;
102 	}
103     // Initialize variables
104 	var i := 0;
105     var temp := false;
106 
107 	// Don't want to exceed the bounds of str1 when checking for the element that is k entries away
108     while i <= |str1|-k
109     // Invariant to stay within bounds
110     invariant 0 <= i <= (|str1|-k) + 1
111     // Invariant to show that when temp is true, it is a substring
112     invariant temp ==> 0 <= i <= (|str1| - k) && isSubstringPred(str1[i..i+k], str2)
113     // Invariant to show that when temp is false, it is not a substring
114     invariant !temp ==> (forall m,n :: (0 <= m < i && n == m+k) ==> isNotSubstringPred(str1[m..n], str2))
115     // Telling dafny that i is that value that is increasing
116     decreases |str1| - k - i
117     {
118         // Get an index from the array position were are at to the array position that is k away and check the substring
119         temp := isSubstring(str1[i..(i + k)], str2);
120         if  temp == true 
121         {
122             return true;
123         }
124         i := i + 1;
125     }
126     return false;
127 }
