135 method maxCommonSubstringLength(str1: string, str2: string) returns (len:nat)
136 	requires (|str1| <= |str2|)
137 	ensures (forall k :: len < k <= |str1| ==> !haveCommonKSubstringPred(k,str1,str2))
138 	ensures haveCommonKSubstringPred(len,str1,str2)
139 {
140     var temp := false;
141     var i := |str1|+1;
142     len := i;
143     // Idea is to start the counter at |str1| and decrement until common string is found
144     while i > 0
145     decreases i
146     // Invariant to stay within bounds
147     invariant 0 <= i <= |str1| + 1
148     // When temp is true, there is a common sub string of size i
149     invariant temp ==> haveCommonKSubstringPred(i, str1, str2)
150     // When temp is false, there is not a common sub string of size i
151     invariant !temp ==> haveNotCommonKSubstringPred(i, str1, str2)
152     // When temp is false, there is no common sub string of sizes >= i
153     invariant !temp ==> (forall k :: i <= k <= |str1| ==> !haveCommonKSubstringPred(k,str1,str2))
154     // When temp is true, there is no common sub string of sizes > i
155     invariant temp ==> (forall k :: (i < k <= |str1|) ==> !haveCommonKSubstringPred(k,str1,str2))
156     {
157         i:= i-1;
158         len := i;
159         temp := haveCommonKSubstring(i, str1, str2);
160         if  temp == true
161         { 
162             break;
163         }
164     }
165     haveCommon0SubstringLemma(str1, str2);
166     return len;
167 }

